fn smallest_list_length(list: &Vec<Vec<i32>>) -> usize {
    // Since the outer list is guaranteed to be non-empty, `min()` on the iterator is safe.
    list
        .iter()
        .map(|inner| inner.len())
        .min()
        .unwrap()
}